#pragma once

#include "robot/core/math.hpp"

#include <vector>

namespace sim {

// Geometry-only corner smoothing shared by deployable planning modules.
// The input and output use world metres. Curvature is signed in 1/m and is
// generated by construction rather than estimated from sampled points.
struct FilletPath {
 std::vector<Vec2> points;
 std::vector<double> curvature_inv_m;
 bool valid{false};
 // True only when every non-collinear interior vertex was replaced by an
 // arc. A caller that needs continuous motion must reject a partial result;
 // a caller that can stop and turn may retain the unsmoothed vertices.
 bool fully_smoothed{false};
};

// Replace each fitting polyline corner by a tangent circular arc. A corner
// fits only when both tangent points lie within half of their adjacent legs,
// which prevents neighbouring fillets from overlapping. Arc chords are no
// longer than max_chord_m. Static-map and chassis checks remain the caller's
// responsibility because geometry alone cannot prove executability.
FilletPath fillet_polyline(const std::vector<Vec2>& route,
 double radius_m, double max_chord_m = 0.10);

} // namespace sim
